export type broadcastAudienceListLogicType = MakeLogicType<
    broadcastAudienceListLogicValues,
    broadcastAudienceListLogicActions,
    BroadcastWizardLogicProps,
    broadcastAudienceListLogicMeta
>

/** The "Upload a list" modal. The wizard saves the file as a recipient list, which becomes the whole audience. */
export const broadcastAudienceListLogic = kea<broadcastAudienceListLogicType>([
    path(['products', 'workflows', 'frontend', 'Broadcasts', 'audience', 'broadcastAudienceListLogic']),
    props({} as BroadcastWizardLogicProps),
    key((props) => props.id),
    connect((props: BroadcastWizardLogicProps) => ({
        actions: [
            broadcastWizardLogic(props),
            ['uploadRecipientList', 'uploadRecipientListSuccess', 'uploadRecipientListFailure'],
        ],
    })),
    actions({
        openListModal: true,
        closeListModal: true,
        setFile: (file: File | null) => ({ file }),
        submitList: true,
        submitListFinished: (error: string | null) => ({ error }),
    }),
    reducers({
        isListModalOpen: [
            false,
            {
                openListModal: () => true,
                closeListModal: () => false,
            },
        ],
        file: [
            null as File | null,
            {
                setFile: (_, { file }) => file,
                openListModal: () => null,
            },
        ],
        creating: [
            false,
            {
                submitList: () => true,
                submitListFinished: () => false,
            },
        ],
        createError: [
            null as string | null,
            {
                submitListFinished: (_, { error }) => error,
                openListModal: () => null,
                setFile: () => null,
            },
        ],
    }),
    selectors({
        submitDisabledReason: [
            (s) => [s.file],
            (file: File | null): string | null => (file ? null : 'Choose a CSV file'),
        ],
    }),
    listeners(({ actions, values }) => ({
        submitList: () => {
            if (!values.file) {
                actions.submitListFinished('Choose a CSV file')
                return
            }
            // The wizard saves the list. The two listeners below finish this submit.
            actions.uploadRecipientList(values.file)
        },
        uploadRecipientListSuccess: () => {
            actions.closeListModal()
            actions.submitListFinished(null)
        },
        uploadRecipientListFailure: ({ error, errorObject }) => {
            actions.submitListFinished(`Couldn't save the list: ${errorObject?.detail || error || 'unknown error'}`)
        },
    })),
])
